INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '棒グラフ問題', '5カ月間のうち、前月と比べて残業時間が増加した月について、その増加時間を合計するといくつになるか。', NULL, '["13時間", "15時間", "17時間", "19時間", "21時間"]', 2, '["前月と比べて増加したのは2月（20→28、+8）、4月（25→34、+9）である。3月と5月は減少している。増加分の合計は8＋9＝17（時間）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '棒グラフ問題', '5支店の平均従業員数を上回っている支店はいくつあるか。', NULL, '["なし", "1つ", "2つ", "3つ", "4つ"]', 2, '["5支店の合計は32＋45＋28＋52＋38＝195（人）、平均は195÷5＝39.0（人）となる。この平均を上回るのはB支店（45人）とD支店（52人）の2つである。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '棒グラフ問題', '4商品の合計販売個数に占める、丙の販売個数の割合はおよそ何%か。最も近いものを選びなさい。', NULL, '["28.1%", "31.3%", "33.8%", "36.3%", "39.4%"]', 3, '["4商品の合計は450＋320＋580＋250＝1,600（個）。丙は580個であるから、割合は580÷1,600＝0.3625となり、百分率で約36.3％となる。よって選択肢Dが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '棒グラフ問題', '予算執行率が80%を超えている部門はいくつあるか。', NULL, '["なし", "1つ", "2つ", "3つ", "4つ"]', 2, '["80％を超えているのは企画（85％）と開発（91％）の2部門である。営業（72％）、総務（68％）、経理（78％）はいずれも80％以下である。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '棒グラフ問題', '平均貯蓄額が最も多い年代と最も少ない年代の差はいくらか。', NULL, '["870万円", "920万円", "950万円", "970万円", "1,010万円"]', 3, '["最も多いのは60代の1,150万円、最も少ないのは20代の180万円である。差は1,150－180＝970（万円）となる。よって選択肢Dが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '棒グラフ問題', '4拠点の合計CO2排出量に占める、最も排出量が多い拠点の割合はおよそ何%か。最も近いものを選びなさい。', NULL, '["28.3%", "31.2%", "34.2%", "37.5%", "40.8%"]', 2, '["4拠点の合計は320＋180＋410＋290＝1,200（トン）。最も排出量が多いのは南拠点の410トンである。割合は410÷1,200＝約0.342となり、百分率で約34.2％となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '棒グラフ問題', '6カ月のうち、目標達成率が100%を超えた月はいくつあるか。', NULL, '["1つ", "2つ", "3つ", "4つ", "5つ"]', 2, '["100％を超えているのは2月（102％）、4月（110％）、5月（101％）の3カ月である。1月（95％）、3月（98％）、6月（97％）はいずれも100％以下である。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '棒グラフ問題', '5校舎のうち、生徒数が多い上位2校舎を合わせると、全体の生徒数のおよそ何%を占めるか。最も近いものを選びなさい。', NULL, '["44.5%", "47.9%", "50.9%", "53.9%", "56.9%"]', 2, '["5校舎の合計は320＋280＋450＋390＋210＝1,650（人）。生徒数が多い順にC校（450人）、D校（390人）である。上位2校舎の合計は450＋390＝840（人）となり、割合は840÷1,650＝約0.509、百分率で約50.9％となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '棒グラフ問題', '前週と比べた増加率が最も大きいのはどの週か。', NULL, '["第1週", "第2週", "第3週", "第4週", "増加した週はない"]', 3, '["前週比の増加率を計算すると、第2週は約15.6％、第3週は約－26.9％（減少）、第4週は約60.5％となる。増加率が最も大きいのは第4週である。よって選択肢Dが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '棒グラフ問題', '5業種の平均年収の平均を上回っている業種はいくつあるか。', NULL, '["なし", "1つ", "2つ", "3つ", "4つ"]', 2, '["5業種の合計は480＋620＋390＋580＋510＝2,580（万円）、平均は2,580÷5＝516（万円）となる。この平均を上回るのは金融（620万円）とIT（580万円）の2業種である。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '折れ線グラフ問題', '前月と比べた増加率が最も大きいのはどの月か。', NULL, '["2月", "3月", "4月", "5月", "6月"]', 2, '["各月の前月比増加率を計算すると、2月は約16.7％、3月は約－7.1％（減少）、4月は約23.1％、5月は約－6.3％（減少）、6月は約20.0％となる。最も増加率が大きいのは4月である。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '折れ線グラフ問題', '生産量に不良率を掛けた不良品数が最も多いのはどの月か。', NULL, '["1月", "2月", "3月", "4月", "すべて同じ"]', 1, '["各月の不良品数（生産量×不良率）を計算すると、1月は4,200×0.021＝88.2、2月は3,800×0.028＝106.4、3月は4,600×0.019＝87.4、4月は4,100×0.025＝102.5（いずれも個）となる。最も多いのは2月である。よって選択肢Bが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '折れ線グラフ問題', '2024年の会員数は、2020年と比較して約何%増加したか。最も近いものを選びなさい。', NULL, '["47.4%", "53.1%", "59.4%", "65.6%", "71.9%"]', 2, '["2020年は3,200人、2024年は5,100人である。増加率は（5,100－3,200）÷3,200＝1,900÷3,200＝約0.594となり、百分率で約59.4％となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '折れ線グラフ問題', '前月からの気温の上昇幅が最も大きいのはどの月か。', NULL, '["2月", "3月", "4月", "5月", "6月"]', 2, '["各月の前月からの気温差を計算すると、2月は＋2.0℃、3月は＋4.0℃、4月は＋5.5℃、5月は＋3.5℃、6月は＋2.5℃となる。最も上昇幅が大きいのは4月である。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '折れ線グラフ問題', '東京店と大阪店の売上高の差が最も大きいのはどの月か。', NULL, '["2月", "3月", "4月", "5月", "6月"]', 4, '["各月の差（東京店－大阪店）を計算すると、1月40、2月45、3月55、4月15、5月50、6月60（いずれも百万円）となる。差が最も大きいのは6月の60百万円である。よって選択肢Eが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '折れ線グラフ問題', '第1週から第5週にかけて、クリック数は約何%増加したか。最も近いものを選びなさい。', NULL, '["58.3%", "64.6%", "70.8%", "76.4%", "82.5%"]', 2, '["第1週は1,200回、第5週は2,050回である。増加率は（2,050－1,200）÷1,200＝850÷1,200＝約0.708となり、百分率で約70.8％となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '折れ線グラフ問題', '売上高に対する広告費の比率（広告費÷売上高）が最も高いのはどの四半期か。', NULL, '["Q1", "Q2", "Q3", "Q4", "すべて同じ"]', 2, '["各四半期の比率を計算すると、Q1は68÷850＝8.0％、Q2は82÷920＝約8.9％、Q3は70÷780＝約9.0％、Q4は88÷1,050＝約8.4％となる。最も比率が高いのはQ3である。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '折れ線グラフ問題', '2020年から2024年までの5年間のうち、前年と比べて輸出量が減少した年は何回あったか。', NULL, '["0回", "1回", "2回", "3回", "4回"]', 2, '["前年比で減少しているのは2021年（820→780）と2024年（950→890）の2回である。2022年と2023年はいずれも前年より増加している。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '折れ線グラフ問題', '前月と比べた来客数の増加率が最も大きいのはどの月か。', NULL, '["2月", "3月", "4月", "5月", "6月"]', 3, '["各月の前月比増加率を計算すると、2月は約12.5％、3月は約18.5％、4月は約12.5％、5月は約33.3％、6月は約6.3％となる。最も増加率が大きいのは5月である。よって選択肢Dが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '折れ線グラフ問題', '6カ月間の在庫回転数の平均を上回っている月はいくつあるか。', NULL, '["なし", "1つ", "2つ", "3つ", "4つ"]', 3, '["6カ月の合計は3.2＋3.8＋2.9＋4.1＋3.5＋4.4＝21.9（回）、平均は21.9÷6＝3.65（回）となる。この平均を上回るのは2月（3.8）、4月（4.1）、6月（4.4）の3カ月である。よって選択肢Dが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '円グラフ問題', '従業員総数が600人であるとき、40代の従業員は何人か。', NULL, '["150人", "165人", "180人", "195人", "210人"]', 2, '["40代の割合は30％であるから、600×0.30＝180（人）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '円グラフ問題', '人件費はマーケティング費のおよそ何倍か。最も近いものを選びなさい。', NULL, '["1.6倍", "1.9倍", "2.1倍", "2.4倍", "2.7倍"]', 2, '["人件費は38％、マーケティング費は18％である。倍率は38÷18＝約2.11となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '円グラフ問題', '回答者総数が3,600人であるとき、「非常に満足」または「満足」と回答した人数は何人か。', NULL, '["1,800人", "1,890人", "1,980人", "2,070人", "2,160人"]', 2, '["「非常に満足」（20％）と「満足」（35％）を合わせると55％となる。回答者総数3,600人に対して、3,600×0.55＝1,980（人）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '円グラフ問題', '全体の売上高をXとおくとき、製品Aと製品Dを合わせた売上高を表す式として正しいものを選びなさい。', NULL, '["2X/5", "9X/20", "11X/25", "23X/50", "12X/25"]', 2, '["製品A（28％）と製品D（16％）を合わせると44％となる。全体をXとすると、44／100＝11／25であるから、求める式は11X/25となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '円グラフ問題', '業務部門のエネルギー消費割合を円グラフの中心角で表すと、およそ何度になるか。', NULL, '["54.0度", "59.4度", "64.8度", "70.2度", "75.6度"]', 2, '["円グラフの中心角は全体360度に占める割合に比例する。業務部門は18％であるため、360×0.18＝64.8（度）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '円グラフ問題', '総売上高が9,600万円であるとき、売上構成比が最も大きい部門と最も小さい部門の売上額の差はいくらか。', NULL, '["1,680万円", "1,800万円", "1,920万円", "2,040万円", "2,160万円"]', 2, '["最も構成比が大きいのは国内営業（35％）、最も小さいのは代理店（15％）である。差の割合は35－15＝20（％）となるので、9,600×0.20＝1,920（万円）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '円グラフ問題', '月間の総支出額が42万円であるとき、食費と水道光熱費を合わせた金額はいくらか。', NULL, '["117,600円", "130,200円", "142,800円", "155,400円", "168,000円"]', 2, '["食費（24％）と水道光熱費（10％）を合わせると34％となる。総支出額42万円に対して、420,000×0.34＝142,800（円）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '円グラフ問題', '回答者総数が850人であるとき、最も割合が大きい出身地と最も割合が小さい出身地の人数の差はいくらか。', NULL, '["196人", "210人", "224人", "238人", "252人"]', 3, '["最も割合が大きいのは関東（42％）、最も割合が小さいのはその他（14％）である。差の割合は42－14＝28（％）となるので、850×0.28＝238（人）となる。よって選択肢Dが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '円グラフ問題', 'バスを利用する人の割合を円グラフの中心角で表すと、およそ何度になるか。', NULL, '["45.0度", "49.5度", "54.0度", "58.5度", "63.0度"]', 2, '["円グラフの中心角は全体360度に占める割合に比例する。バスは15％であるため、360×0.15＝54.0（度）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '円グラフ問題', '全体の売上高をYとおくとき、ECサイトと代理店を合わせた売上高を表す式として正しいものを選びなさい。', NULL, '["2Y/5", "9Y/20", "Y/2", "11Y/20", "3Y/5"]', 2, '["ECサイト（32％）と代理店（18％）を合わせると50％となる。全体をYとすると、50／100＝1／2であるから、求める式はY/2となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '帯グラフ問題', '「非常に期待している」または「やや期待している」と回答した人の合計割合を比較したとき、ドイツは日本より何ポイント高いか。', NULL, '["8pt", "10pt", "12pt", "14pt", "16pt"]', 2, '["日本の合計は20＋38＝58（％）。ドイツの合計は28＋42＝70（％）。差は70－58＝12（ポイント）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '帯グラフ問題', '2020年の全体の販売額をMとおくとき、EC（通信販売）とその他を合わせた販売額を表す式として正しいものを選びなさい。', NULL, '["3M/10", "7M/20", "2M/5", "9M/20", "M/2"]', 1, '["2020年のEC（通信販売）は20％、その他は15％であり、合計は20＋15＝35（％）である。全体をMとすると、35／100＝7／20であるから、求める式は7M/20となる。よって選択肢Bが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '帯グラフ問題', '2010年の百貨店の販売額をDとおくとき、2010年における全体の販売額を表す式として正しいものを選びなさい。', NULL, '["7D/3", "3D", "10D/3", "4D", "14D/3"]', 2, '["2010年の百貨店の割合は30％である。全体をWとすると、W：D＝100：30という比の関係が成り立つ。これを解くと30W＝100Dとなり、W＝100D/30＝10D/3と導かれる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '帯グラフ問題', '「週3日以上」または「週1〜2日」テレワークを実施していると回答した割合の合計は、2022年度から2024年度にかけて何ポイント増加したか。', NULL, '["9pt", "12pt", "15pt", "18pt", "21pt"]', 2, '["2022年度の合計は18＋25＝43（％）。2024年度は28＋30＝58（％）である。差は58－43＝15（ポイント）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '帯グラフ問題', '10代と50代において、「毎日利用する」または「週に数回利用する」と回答した割合の合計を比較したとき、その差は何ポイントか。', NULL, '["36pt", "40pt", "44pt", "48pt", "52pt"]', 3, '["10代の合計は55＋28＝83（％）。50代の合計は12＋23＝35（％）。差は83－35＝48（ポイント）となる。よって選択肢Dが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '帯グラフ問題', '「非常に関心がある」または「やや関心がある」と回答した人の合計割合を比較したとき、スウェーデンは日本より何ポイント高いか。', NULL, '["9pt", "12pt", "15pt", "18pt", "21pt"]', 2, '["日本の合計は25＋40＝65（％）。スウェーデンの合計は45＋35＝80（％）。差は80－65＝15（ポイント）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '帯グラフ問題', '2025年の全体の発電電力量をMとおくとき、再生可能エネルギーと原子力を合わせた発電電力量を表す式として正しいものを選びなさい。', NULL, '["3M/10", "7M/20", "2M/5", "19M/50", "9M/20"]', 3, '["2025年の再生可能エネルギーは18％、原子力は20％であり、合計は18＋20＝38（％）である。全体をMとすると、38／100＝19／50であるから、求める式は19M/50となる。よって選択肢Dが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '帯グラフ問題', '2005年の水力による発電電力量をHとおくとき、2005年における全体の発電電力量を表す式として正しいものを選びなさい。', NULL, '["6H", "8H", "10H", "12H", "15H"]', 2, '["2005年の水力の割合は10％である。全体をWとすると、W：H＝100：10という比の関係が成り立つ。これを解くと10W＝100Hとなり、W＝10Hと導かれる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '帯グラフ問題', '「積極的に推進」または「一部推進」していると回答した割合の合計は、2021年度から2023年度にかけて何ポイント増加したか。', NULL, '["6pt", "9pt", "12pt", "15pt", "18pt"]', 2, '["2021年度の合計は20＋30＝50（％）。2023年度は28＋34＝62（％）である。差は62－50＝12（ポイント）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '帯グラフ問題', '20代と60代において、「非常に意識している」または「やや意識している」と回答した割合の合計を比較したとき、その差は何ポイントか。', NULL, '["13pt", "16pt", "19pt", "22pt", "25pt"]', 2, '["20代の合計は30＋32＝62（％）。60代の合計は15＋28＝43（％）。差は62－43＝19（ポイント）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', 'data:image/png;base64,', NULL);
